-- Transactional PostgreSQL role rehearsal, NOT an Auth/MFA JWT end-to-end test.
-- Synthetic identities have no passwords/sessions; no real Storage bytes written; every effect rolls back.
begin;
do $$begin if not exists(select 1 from spot_private.privacy_environment where environment='staging')or(select phase from spot_private.photo_cutover_control)<>'PAUSED'or not(select paused from spot_private.retention_control)then raise exception 'STAGING_SAFE_STATE_REQUIRED';end if;if exists(select 1 from auth.users where id::text like 'f2500000-%')then raise exception 'FIXTURE_COLLISION';end if;end$$;
insert into auth.users(id,email,is_anonymous,raw_user_meta_data)select ('f2500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'moderation-fixture-'||n||'@example.invalid',false,'{"moderation_fixture":true}'::jsonb from generate_series(1,3)n;
insert into spot_private.account_eligibility(user_id,status,declared_age)select id,'eligible',25 from auth.users where id::text like 'f2500000-%';
insert into spot_private.consent_state(user_id,status,version)select id,'active','dating-staging-v1'from auth.users where id::text like 'f2500000-%';
-- Fixture-scoped canary is uncommitted and restores automatically at rollback.
update spot_private.photo_cutover_control set phase='CANARY',canary_users=array['f2500000-0000-4000-8000-000000000001'::uuid,'f2500000-0000-4000-8000-000000000002'::uuid,'f2500000-0000-4000-8000-000000000003'::uuid];
insert into spot_private.validated_photos(photo_path,user_id,preview,canonical_sha,canonical_bytes,source_format,source_width,source_height)select id::text||'/fixture.jpg',id,'data:image/jpeg;base64,YQ==',repeat('a',64),1,'JPEG',1,1 from auth.users where id::text like 'f2500000-%';
insert into spot_private.photo_lifecycle_sets(photo_path,user_id,state,writer,not_before)select id::text||'/fixture.jpg',id,'ready','settled',now()+interval '1 day'from auth.users where id::text like 'f2500000-%';
insert into public.profiles(id,name,age,gender,preference,photo_path)select id,'MODERATION SYNTHETIC',25,'M','ALL',id::text||'/fixture.jpg'from auth.users where id::text like 'f2500000-%';
-- SQL role simulation only; no fixture can authenticate, and rows roll back.
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at)values('f2530000-0000-4000-8000-000000000001','f2500000-0000-4000-8000-000000000002','totp','verified',null,now(),now()),('f2530000-0000-4000-8000-000000000002','f2500000-0000-4000-8000-000000000003','totp','verified',null,now(),now());
insert into spot_private.moderation_roles(user_id,role)values('f2500000-0000-4000-8000-000000000002','MODERATOR'),('f2500000-0000-4000-8000-000000000003','ADMIN');
insert into spot_private.reports(id,reporter_id,target_id,reason,details,created_at)select ('f2510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'f2500000-0000-4000-8000-000000000002','f2500000-0000-4000-8000-000000000001','other','Synthetic case reference only','2026-01-01'from generate_series(1,151)n;
set local role authenticated;select set_config('request.jwt.claim.sub','f2500000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"aal":"aal2"}',true);
do $$begin begin perform public.moderation_queue();raise exception 'USER_ALLOWED';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claim.sub','f2500000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"aal":"aal1"}',true);
do $$begin begin perform public.moderation_queue();raise exception 'MFA_BYPASS';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
do $$declare p jsonb;t timestamptz;i uuid;last jsonb;seen integer:=0;begin loop p:=public.moderation_queue('open',t,i,50);seen:=seen+jsonb_array_length(p->'items');exit when not(p->>'more')::boolean;last:=p->'items'->-1;t:=(last->>'created_at')::timestamptz;i:=(last->>'id')::uuid;end loop;if seen<>151 then raise exception 'PAGINATION_LOSS';end if;end$$;
select public.moderation_action('f2510000-0000-4000-8000-000000000001','claim','OTHER','f2520000-0000-4000-8000-000000000001',0);
select public.moderation_action('f2510000-0000-4000-8000-000000000001','claim','OTHER','f2520000-0000-4000-8000-000000000001',0);
select set_config('request.jwt.claim.sub','f2500000-0000-4000-8000-000000000003',true);
do $$begin begin perform public.moderation_action('f2510000-0000-4000-8000-000000000001','dismiss','OTHER','f2520000-0000-4000-8000-000000000002',1);raise exception 'CLAIM_BYPASS';exception when raise_exception then if sqlerrm<>'MODERATION_CLAIMED'then raise;end if;end;end$$;
select public.moderation_action('f2510000-0000-4000-8000-000000000002','ban','OTHER','f2520000-0000-4000-8000-000000000003',0);
select set_config('request.jwt.claim.sub','f2500000-0000-4000-8000-000000000001',true);
do $$begin if not public.my_account_status()then raise exception 'BAN_BYPASS';end if;if(public.my_rights_page('account')->>'owner_id')<>'f2500000-0000-4000-8000-000000000001'then raise exception 'RIGHTS_BLOCKED';end if;begin perform public.moderation_queue();raise exception 'BANNED_ADMIN_BYPASS';exception when insufficient_privilege then null;end;end$$;
reset role;
do $$declare token uuid;begin perform public.photo02_begin_account_deletion('f2500000-0000-4000-8000-000000000001');token:=public.claim_photo_account_cleanup('f2500000-0000-4000-8000-000000000001');if token is null then raise exception 'DELETE_BLOCKED';end if;perform public.prepare_account_deletion('f2500000-0000-4000-8000-000000000001');delete from auth.users where id='f2500000-0000-4000-8000-000000000001';perform public.finish_photo_account_cleanup('f2500000-0000-4000-8000-000000000001',token);if exists(select 1 from spot_private.reports where target_id='f2500000-0000-4000-8000-000000000001')or exists(select 1 from spot_private.moderation_audit where target_id='f2500000-0000-4000-8000-000000000001')then raise exception 'DELETE_RESIDUE';end if;end$$;
select 'PASS' as user_denied,'PASS' as aal1_denied,'PASS' as pagination151,'PASS' as claim_retry,'PASS' as competing_claim_denied,'PASS' as ban_enforcement,'PASS' as banned_rights,'PASS' as banned_delete;
rollback;
select jsonb_build_object('fixture_accounts',(select count(*)from auth.users where id::text like 'f2500000-%'),'fixture_reports',(select count(*)from spot_private.reports where id::text like 'f2510000-%'),'fixture_roles',(select count(*)from spot_private.moderation_roles where user_id::text like 'f2500000-%'),'fixture_objects',(select count(*)from storage.objects where bucket_id='profile-photos'and name like 'f2500000-%'),'accounts',(select count(*)from auth.users),'profiles',(select count(*)from public.profiles),'objects',(select count(*)from storage.objects where bucket_id='profile-photos'),'phase',(select phase from spot_private.photo_cutover_control),'retention_paused',(select paused from spot_private.retention_control))as postflight;
